using HPD.Agent.Audio.Runtime.Providers;
using HPD.Agent.Audio.Runtime.Routing;
using HPD.Agent.Audio.Runtime.Tools;
using HPD.Agent.Authority;

namespace HPD.Agent.LiveAudio.Contracts.Tests;

public sealed class RouteCutoverCoordinatorTests
{
    [Fact] public void Authorized_prepared_provider_commits_cutover(){var f=Fixture();Assert.IsType<RouteCutoverResult.Committed>(RouteCutoverCoordinator.Commit(OperationId.Create(),f.Evidence));}
    [Fact] public void Provider_identity_and_generation_are_authenticated(){var f=Fixture();var wrong=new ProviderParticipantPlan(f.Plan.ParticipantId,ProviderId.Create(),f.Plan.Generation,f.Plan.RouteGeneration,f.Plan.Authority,f.Plan.CatalogFingerprint,1);var r=RouteCutoverCoordinator.Commit(OperationId.Create(),f.Evidence with{Provider=f.Evidence.Provider with{Plan=wrong}});Assert.Equal("route-provider-evidence-mismatch",Assert.IsType<RouteCutoverResult.Rejected>(r).SafeCode.ToString());}
    [Fact] public void Unauthorized_preparation_cannot_cut_over(){var f=Fixture();var p=new RoutePreparationState(f.Evidence.Preparation.Route,new(2,RoutePreparationPhase.OwnerClaimed,OwnerSliceId.S5));Assert.Equal("route-cutover-not-authorized",Assert.IsType<RouteCutoverResult.Rejected>(RouteCutoverCoordinator.Commit(OperationId.Create(),f.Evidence with{Preparation=p})).SafeCode.ToString());}
    [Fact] public void Authenticated_cutover_enables_composite_tool_resume(){var f=Fixture();var route=Assert.IsType<RouteCutoverResult.Committed>(RouteCutoverCoordinator.Commit(OperationId.Create(),f.Evidence)).Receipt;var tool=Projected(f.Authority,f.Output,f.Tool);var resumed=Assert.IsType<ToolTransactionResult.Applied>(ToolCompositeResume.Resume(tool,OperationId.Create(),route,32));Assert.Equal(ToolTransactionPhase.ToolContinuationAuthorized,resumed.State.Snapshot.Phase);}
    [Fact] public void Resume_rejects_stale_route_without_advancing(){var f=Fixture();var route=Assert.IsType<RouteCutoverResult.Committed>(RouteCutoverCoordinator.Commit(OperationId.Create(),f.Evidence)).Receipt;var other=RouteGenerationId.Create();var authority=ExpectedAuthorityVectorV1.Create(f.Authority.Session,[new AuthorityAxisValueV1.Output(f.Output),new AuthorityAxisValueV1.Tool(f.Tool),new AuthorityAxisValueV1.Route(other),new AuthorityAxisValueV1.Provider(f.Plan.Generation)]);var tool=Projected(authority,f.Output,f.Tool);var rejected=Assert.IsType<ToolTransactionResult.Rejected>(ToolCompositeResume.Resume(tool,OperationId.Create(),route,32));Assert.Equal("tool-route-authority-mismatch",rejected.SafeCode.ToString());Assert.Equal(ToolTransactionPhase.ToolResultProjected,rejected.State.Snapshot.Phase);}
    private static (RouteCutoverEvidence Evidence,ProviderParticipantPlan Plan,ExpectedAuthorityVectorV1 Authority,OutputGenerationId Output,ToolGenerationId Tool) Fixture(){var s=new SessionAuthorityStampV1(RuntimeGenerationId.Create(),LiveSessionId.Create());var pg=ProviderGenerationId.Create();var prior=RouteGenerationId.Create();var rg=RouteGenerationId.Create();var og=OutputGenerationId.Create();var tg=ToolGenerationId.Create();var old=ExpectedAuthorityVectorV1.Create(s,[new AuthorityAxisValueV1.Output(og),new AuthorityAxisValueV1.Tool(tg),new AuthorityAxisValueV1.Route(prior),new AuthorityAxisValueV1.Provider(pg)]);var route=new CompiledRoute(OperationId.Create(),ProviderId.Create(),rg,old,Hash(1),Hash(2));var admission=RouteAuthorityAdmission.Admit(route,new JournalPositionV1(s,4));var prep=new RoutePreparationState(route,new(3,RoutePreparationPhase.CutoverAuthorized,OwnerSliceId.S5));var plan=new ProviderParticipantPlan(ParticipantId.Create(),route.ProviderId,pg,rg,admission.Authority,Hash(1),1);return(new(prep,new(2,ProviderParticipantPhase.Effective,plan,0,null),admission),plan,admission.Authority,og,tg);}
    private static ToolTransactionState Projected(ExpectedAuthorityVectorV1 a,OutputGenerationId o,ToolGenerationId t){var state=ToolTransactionSupervisor.Create(new(OperationId.Create(),t,o,a,new MonotonicStampV1(ClockDomainId.Create(),BootId.Create(),100),true));foreach(var p in new[]{ToolTransactionPhase.ToolControlRecorded,ToolTransactionPhase.ToolArgumentsFinalized,ToolTransactionPhase.ToolApprovalDecided,ToolTransactionPhase.ToolDispositionChosen,ToolTransactionPhase.ToolOwnerClaimed,ToolTransactionPhase.ToolDispatchAuthorized,ToolTransactionPhase.ToolEntryIntentRecorded,ToolTransactionPhase.ToolExternalBoundaryEntered})state=A(state,new ToolTransactionCommand.Advance(OperationId.Create(),state.Snapshot.Revision,p,1));state=A(state,new ToolTransactionCommand.AdmitEffectEvidence(OperationId.Create(),8,true));state=A(state,new ToolTransactionCommand.Advance(OperationId.Create(),9,ToolTransactionPhase.ToolResultFinalized,1));return A(state,new ToolTransactionCommand.Advance(OperationId.Create(),10,ToolTransactionPhase.ToolResultProjected,1));}
    private static ToolTransactionState A(ToolTransactionState s,ToolTransactionCommand c)=>Assert.IsType<ToolTransactionResult.Applied>(ToolTransactionSupervisor.Apply(s,c,32)).State;
    private static Hash256 Hash(byte b)=>Hash256.Compute(new[]{b});
}
